import java.util.*; 
public class PIEFLAVORED{
private static final long MODULUS = 998244353;
   public static void main(String[] args) 
   {
      Scanner input = new Scanner(System.in);
      int n = input.nextInt();
      long kLong = input.nextLong();
      if(kLong >= n)
      {
         System.out.println("0");
      }
      else
      {
      int k = (int)kLong;
      int r = n - k;
      long[] chooseArr = new long[r+1];
      chooseArr[0] = 1L;
      long numerator = 1L;
      long denominator = 1L;
      for(int i = 1; i <= r; i++)
      {
         numerator = (numerator * (r + 1 - i)) % MODULUS;
         denominator = (denominator * i) % MODULUS;
         chooseArr[i] = (numerator * power(denominator, MODULUS - 2)) % MODULUS;
      }
      long totalAns = 0;
      long signFlag = 1;
      for(int i = 0; i <= r; i++)
      {
         totalAns += power((long)(r - i), (long)n) * signFlag * chooseArr[i];
         totalAns %= MODULUS;
         signFlag = -signFlag;
      }
      totalAns = (totalAns * choose((long)n, (long)k)) % MODULUS;
      if(k > 0)
      {
         totalAns = (totalAns * 2) % MODULUS;
      }
      if(totalAns < 0)
      {
         totalAns += MODULUS;
      }
      System.out.println("" + totalAns);
      }
   }
public static long choose(long n, long k)  
    { 
      long num = 1;
      long denom = 1;
      for(int i = (int)(n - k + 1); i <= n; i++)
      {
         num = (num * i) % MODULUS;
      } 
      for(int i = 1; i <= k; i++)
      {
         denom = (denom * i) % MODULUS;
      } 
      denom = power(denom, MODULUS - 2);
      return (num * denom) % MODULUS;
    } 
public static long power(long base, long exp) 
{ 
    long result = 1;      
    base = base % MODULUS;
    while (exp > 0) 
    { 
        if ((exp & 1) == 1) 
        {    result = (result * base) % MODULUS;}
        exp >>= 1;  
        base = (base * base) % MODULUS; 
    } 
    return result; 
}
}
